// ================= SITIO A: mano robotica barajando (E1) y cartera con $100 (E2) =================
const A_CAM = [P(0, 540, 880, 1.0), P(PARA1, 540, 900, 1.25), P(IMAG, 540, 1000, 1.0), P(CAFE1, 440, 1000, 1.1), P(NOV1 + 0.8, 640, 1000, 1.1)];
const AF = P(NOV1 + 0.8, 640, 1000, 1.1);
const PXA = 540 + (540 - AF.x) * AF.zoom;
const PYA = 1000 + (1300 - AF.y) * AF.zoom;
const PERM = [[0, 1, 2, 3], [2, 3, 0, 1], [1, 3, 0, 2], [3, 0, 2, 1], [3, 2, 0, 1]];
const SitioA: React.FC = () => {
  const {s, spr} = useS();
  const times = [0, CAMBIABA, ORDEN1, COMPRAS, PARA1];
  const slotX = (j: number) => 540 + (j - 1.5) * 225;
  const ez = {...clamp, easing: Easing.inOut(Easing.cubic)};
  const seg = Math.max(0, Math.min(3, times.findIndex((t, i) => i < 4 && s >= t && s < times[i + 1])));
  const fr = ro(s, times[seg], times[seg + 1]);
  const bump = s >= PARA1 ? 0 : Math.sin(Math.PI * fr) * 130;
  const rx = [0, 1, 2, 3].map((i) => interpolate(s, times, PERM.map((p) => slotX(p[i])), ez));
  const rojoL = ro(s, COBRARTE, COBRARTE + 0.45);
  const sale = eio(ro(s, IMAG - 0.3, IMAG + 0.7));
  const cart = spr(IMAG, 10, 110);
  const wy = 1300 + (1 - cart) * 1400;
  const tsh = ro(s, COBRARTE, COBRARTE + 0.3);
  return (
    <AbsoluteFill>
      <Camara paradas={A_CAM}>
        <Textura tipo="papel" base="radial-gradient(circle at 50% 40%, #3a414d 0%, #1d222b 66%, #0b0d12 100%)" linea="rgba(255,200,61,0.16)" luz="rgba(255,200,61,0.12)" semilla={31} />
        <Brillo x={540} y={980} r={620} color="rgba(255,200,61,0.26)" />
        <svg width={1080} height={1920} style={{position: 'absolute', inset: 0}}>
